import "./home.css"
import gsap from "gsap";
import { useGSAP } from "@gsap/react"

const Blurred = () => {
    useGSAP( () => {
        gsap.to(".box1",{
            x:800,
            duration : 1,
            repeat: 5,
            ease: 'power1.inOut' ,
        })
    })
    return(
        <div className="container blurred-loading">
            <div className="row loading-columns">
                <div className="col-md-3 loading-column">
                    <div className="box1"></div>
                </div>
                <div className="col-md-3 loading-column">
                    <div className="box1"></div>
                </div>
                <div className="col-md-3 loading-column">
                    <div className="box1"></div>
                </div>
            </div>
        </div>
    )
}

export default Blurred
